import {textEffectState,textEffectSVG,textEffectHTML,textUnits} from './text-effects-core.mjs';
export function textEffectsTool({change}){
 const $=id=>document.getElementById('effect-'+id),reduce=matchMedia('(prefers-reduced-motion: reduce)');let state=textEffectState(),active=false,playing=false,frame=0,last=0,lastPaint=0;
 function paint(){$('preview').innerHTML=textEffectSVG(state);$('phase').value=Math.round(state.phase*100);$('phase-value').textContent=Math.round(state.phase*100)+'%'}
 function tick(now){frame=0;if(!active||!playing||reduce.matches||document.hidden)return;if(last)state.phase=(state.phase+(now-last)/1000/(state.duration+(textUnits(state.text,state.unit).length-1)*state.stagger))%1;last=now;if(now-lastPaint>1000/30){paint();lastPaint=now}frame=requestAnimationFrame(tick)}
 function sync(){cancelAnimationFrame(frame);frame=0;last=0;if(reduce.matches||state.animation==='none')playing=false;$('play').disabled=reduce.matches||state.animation==='none';$('play').textContent=reduce.matches?'Reduced motion enabled':state.animation==='none'?'Choose an animation':playing?'Pause animation':'Play animation';$('play').setAttribute('aria-pressed',String(playing));if(active&&playing&&!document.hidden)frame=requestAnimationFrame(tick)}
 function draw(){$('weight').max=state.font==='dm'?700:800;for(const key of Object.keys(state))if($(key))$(key).value=state[key];for(const key of ['size','weight','radius','strength','depth','lightX','lightY','duration','stagger'])if($(key+'-value'))$(key+'-value').textContent=state[key]+(['size','radius','depth'].includes(key)?' px':['duration','stagger'].includes(key)?' s':'');paint();sync();change()}
 for(const key of Object.keys(state))if($(key)&&key!=='phase')$(key).oninput=e=>{state=textEffectState({...state,[key]:e.target.value});draw()};
 $('phase').oninput=e=>{playing=false;state.phase=Math.max(0,Math.min(1,Number(e.target.value)/100));paint();sync();change()};$('play').onclick=()=>{playing=!playing;if(playing&&state.phase===1)state.phase=0;sync()};$('reset').onclick=()=>{state=textEffectState({text:state.text,font:state.font});playing=false;draw()};
 $('preview').onpointermove=e=>{if(state.appearance!=='spotlight')return;const r=$('preview').getBoundingClientRect();state.lightX=Math.round(Math.max(0,Math.min(960,(e.clientX-r.left)/r.width*960)));state.lightY=Math.round(Math.max(0,Math.min(540,(e.clientY-r.top)/r.height*540)));paint();$('lightX').value=state.lightX;$('lightY').value=state.lightY;$('lightX-value').textContent=state.lightX;$('lightY-value').textContent=state.lightY;change()};
 reduce.addEventListener('change',sync);document.addEventListener('visibilitychange',sync);draw();return {get:()=>({...state}),set:s=>{if(s){state=textEffectState(s);playing=false;draw()}},content:(text,font)=>{state=textEffectState({...state,text,font});paint()},activate:v=>{active=v;sync()},svg:()=>textEffectSVG(state),html:()=>textEffectHTML(state)}
}
